package ktanesolver.module.modded.regular.sonicknuckles;
import java.util.List;import java.util.Map;import org.springframework.stereotype.Service;import ktanesolver.annotation.ModuleInfo;import ktanesolver.dto.ModuleCatalogDto;import ktanesolver.entity.*;import ktanesolver.enums.ModuleType;import ktanesolver.logic.*;import ktanesolver.module.modded.regular.sonicknuckles.SonicKnucklesInput.*;
@Service @ModuleInfo(type=ModuleType.SONIC_KNUCKLES,id="sonicKnuckles",name="Sonic & Knuckles",category=ModuleCatalogDto.ModuleCategory.MODDED_REGULAR,description="Choose the off-zone sound and calculate Robotnik hits and timing.",tags={"sounds","timer","video-game","two-stages"})
public class SonicKnucklesSolver extends AbstractModuleSolver<SonicKnucklesInput,SonicKnucklesOutput>{
 private static final Map<Zone,List<Sound>> FEATURED=Map.of(Zone.MUSHROOM_HILL,List.of(Sound.BLUE_SPHERE,Sound.INVINCIBILITY_THEME,Sound.JUMP,Sound.LIGHTNING_SHIELD),Zone.FLYING_BATTERY,List.of(Sound.BOSS_THEME,Sound.FLAG_BUMP,Sound.NOT_ENOUGH_RINGS,Sound.SPECIAL_STAGE),Zone.SANDOPOLIS,List.of(Sound.ANTIGRAV_FUNNEL,Sound.FLYING_BATTERY,Sound.MUSHROOM_BOUNCE,Sound.TELEPORT),Zone.LAVA_REEF,List.of(Sound.BADNIK_KILL,Sound.BREATHE,Sound.LAMPPOST,Sound.SPIKES),Zone.SKY_SANCTUARY,List.of(Sound.ALARM,Sound.BRIDGE_UP,Sound.FLYING_BATTERY_ZONE_THEME,Sound.REGULAR_SHIELD),Zone.DEATH_EGG,List.of(Sound.BUMPER,Sound.DROWN_WARNING,Sound.RING_CASH_IN,Sound.SPIN));
 @Override protected SolveResult<SonicKnucklesOutput>doSolve(RoundEntity r,BombEntity b,ModuleEntity m,SonicKnucklesInput i){if(i==null||i.zone()==null||i.heroSound()==null||i.badnikSound()==null||i.monitorSound()==null||i.hero()==null||i.badnik()==null||i.monitor()==null)return failure("Enter the zone, three sounds, and all three objects");if(i.score()<1||i.rings()<0)return failure("Score must be positive and rings non-negative");boolean h=!FEATURED.get(i.zone()).contains(i.heroSound()),d=!FEATURED.get(i.zone()).contains(i.badnikSound()),n=!FEATURED.get(i.zone()).contains(i.monitorSound());if((h?1:0)+(d?1:0)+(n?1:0)!=1)return failure("Exactly one of the three sounds must be absent from the selected zone");String object=h?"hero":d?"badnik":"monitor";int correct=h?i.hero().code:d?i.badnik().code:i.monitor().code;int other=(h?0:i.hero().code)+(d?0:i.badnik().code)+(n?0:i.monitor().code);int root=((correct*i.score()-1)%9)+1;int hits=(root+other)%10+1;boolean inverse=i.hero()==Hero.KNUCKLES||i.badnik()==Badnik.GHOST||i.monitor()==Monitor.RUNNING_BOOTS;storeState(m,Map.of("badnik",display(i.badnik().name()),"monitor",display(i.monitor().name())));return success(new SonicKnucklesOutput(object,i.rings()%20,hits,inverse?"odd":"even",inverse?"even":"odd"));}
 static int hits(int correct,int score,int a,int c){return ((((correct*score-1)%9)+1)+a+c)%10+1;}private static String display(String s){return java.util.Arrays.stream(s.toLowerCase().split("_")).map(x->Character.toUpperCase(x.charAt(0))+x.substring(1)).collect(java.util.stream.Collectors.joining(" "));}
}
